1	// In-memory live-editing state layered on top of a loaded LandscapeSnapshot,
2	// plus validation and residual-CLI command-line generation.
3	//
4	// Pure, DOM-free, framework-free — see web/src/model.test.ts and the
5	// governing plan at residual/iterations/view-live-editing-plan.md (Phase 4).
6	// Sits between the embedded snapshot JSON (src/view/snapshot.rs's
7	// `LandscapeSnapshot`) and import-parser.ts's CLI-text parsing: this module
8	// owns "what has the user added/changed/toggled this session" plus
9	// validation, and turns that state back into `residual add`/`residual
10	// update` command-line text.
11	//
12	// Design notes (decisions made beyond the task sketch, documented per
13	// instructions):
14	//
15	// - `SnapshotAttractor` includes `description` even though the sketch in the
16	//   task omitted it: `residual add attractor --description` is a *required*
17	//   flag per web/generated/cli-schema.json ("add attractor" ->
18	//   description: required=true), and src/view/snapshot.rs's
19	//   `SnapshotAttractor` carries it too. Dropping it would make
20	//   `toCommandLines` unable to ever emit a valid `add attractor` line.
21	// - Required-fields ground truth for validation comes from
22	//   web/generated/cli-schema.json, NOT the plan prose. Per that schema,
23	//   `add stressor`/`add purpose` require description, attractor-id and
24	//   naive-change/feature — but NOT outcomes (outcomes: required=false in the
25	//   schema for both). `isForceValid` therefore does not check outcomes.
26	// - `add stressor`/`add purpose` have no `--add-component` flag in the
27	//   schema (only `update stressor`/`update purpose` do), and `add stressor`/
28	//   `add purpose` have no `--force-id` flag either — the id is assigned
29	//   server-side and only ever appears in stdout on success ("Added stressor
30	//   S-NN"). So a freshly *added* force's toggled components can never ride
31	//   on its own `add` line, AND the follow-up `update <type> --add-component
32	//   ...` line can never reference the force's `tempId` as a literal
33	//   `--force-id` value (that string will never exist in stressors.csv/
34	//   residues.csv, so the generated script would silently fail). Instead,
35	//   `toCommandLines` wraps the `add` line in a shell-variable capture
36	//   (`NEW_1_ID=$(residual add stressor ... | grep -oE '[A-Z]+-[0-9]+' |
37	//   tail -1)`) and has the synthetic `update` line reference `"$NEW_1_ID"`.
38	//   This capture-wrapped line is intentionally not `parseImportText`-
39	//   round-trippable — it's a shell construct, not a plain CLI invocation.
40	// - Personas and terms are tracked as their own add/update buckets even
41	//   though the plan's explicit ordering list only names "components,
42	//   attractors, personas, forces" (terms are not mentioned). Since terms
43	//   don't participate in the NKP matrix and aren't named in the ordering
44	//   rule, this module places them last, after forces, in both the add and
45	//   update phases — a conservative extension of the rule, not a
46	//   contradiction of it.
47	
48	/** A landscape attractor, as it appears in the embedded snapshot or is added this session. */
49	export interface SnapshotAttractor {
50	  id: string;
51	  name: string;
52	  /** Required by `residual add attractor --description`; see module notes. */
53	  description: string;
54	  positiveState: string;
55	  negativeState: string;
56	}
57	
58	/** A landscape component (NKP matrix column). */
59	export interface SnapshotComponent {
60	  name: string;
61	  description: string;
62	  status: "proposed" | "actual";
63	  architectureSet: string;
64	}
65	
66	/** A stressor or purpose force (NKP matrix row), with its coupled components. */
67	export interface SnapshotForce {
68	  id: string;
69	  kind: "stressor" | "purpose";
70	  description: string;
71	  attractorId: string;
72	  /** `naive_change` for stressors, `feature` for purposes. */
73	  naiveChangeOrFeature: string;
74	  outcomes: string;
75	  shortname: string;
76	  /** Component names currently coupled to this force via residues.csv. */
77	  components: string[];
78	}
79	
80	/** A defense/below-table persona (name + role), not part of the NKP matrix. */
81	export interface SnapshotPersona {
82	  name: string;
83	  role: string;
84	  concerns?: string;
85	  desires?: string;
86	}
87	
88	/** A lexicon term, not part of the NKP matrix. */
89	export interface SnapshotTerm {
90	  term: string;
91	  definition: string;
92	  domain?: string;
93	  related?: string;
94	}
95	
96	/** A newly-added force this session, not yet assigned a real force id by the CLI. */
97	export type AddedForce = SnapshotForce & { tempId: string };
98	
99	/** Partial update to an existing (or newly-added) force, keyed by real id or tempId. */
100	export type ForceUpdate = Partial<Omit<SnapshotForce, "id" | "kind">>;
101	
102	/** Partial update to an existing attractor, keyed by real id. */
103	export type AttractorUpdate = Partial<Omit<SnapshotAttractor, "id">>;
104	
105	/** Partial update to an existing component, keyed by name (components have no separate id). */
106	export type ComponentUpdate = Partial<Omit<SnapshotComponent, "name">>;
107	
108	/** Partial update to an existing persona, keyed by name. */
109	export type PersonaUpdate = Partial<Omit<SnapshotPersona, "name">>;
110	
111	/** Partial update to an existing term, keyed by term text. */
112	export type TermUpdate = Partial<Omit<SnapshotTerm, "term">>;
113	
114	/**
115	 * Everything the user has added or changed this editing session, layered on
116	 * top of a base snapshot loaded from the embedded `residual-snapshot` JSON.
117	 */
118	export interface PendingState {
119	  baseAttractors: SnapshotAttractor[];
120	  baseComponents: SnapshotComponent[];
121	  baseForces: SnapshotForce[];
122	  basePersonas: SnapshotPersona[];
123	  baseTerms: SnapshotTerm[];
124	
