126	  addedComponents: SnapshotComponent[];
127	  addedForces: AddedForce[];
128	  addedPersonas: SnapshotPersona[];
129	  addedTerms: SnapshotTerm[];
130	
131	  /** Keyed by real attractor id. */
132	  updatedAttractors: Record<string, AttractorUpdate>;
133	  /** Keyed by component name. */
134	  updatedComponents: Record<string, ComponentUpdate>;
135	  /** Keyed by real force id OR an added force's tempId. */
136	  updatedForces: Record<string, ForceUpdate>;
137	  /** Keyed by persona name. */
138	  updatedPersonas: Record<string, PersonaUpdate>;
139	  /** Keyed by term text. */
140	  updatedTerms: Record<string, TermUpdate>;
141	}
142	
143	/** Required (non-outcomes) field names for a stressor/purpose, per cli-schema.json. */
144	export type RequiredForceField = "description" | "attractorId" | "naiveChangeOrFeature";
145	
146	export const REQUIRED_FORCE_FIELDS: readonly RequiredForceField[] = [
147	  "description",
148	  "attractorId",
149	  "naiveChangeOrFeature",
150	];
151	
152	/** One resolved item in the fixed add/update, component/attractor/persona/term/force emission order. */
153	export interface OrderedEntry {
154	  bucket: "component" | "attractor" | "persona" | "term" | "force";
155	  action: "add" | "update";
156	  /** Real id/name/term/tempId identifying the entry within its bucket. */
157	  key: string;
158	}
159	
160	/**
161	 * Returns whether a force (added, or the effective merge of a base force
162	 * with its pending update) is valid: every field in REQUIRED_FORCE_FIELDS is
163	 * non-empty, AND at least one component is toggled on (per the plan: "no
164	 * components selected is invalid"). Outcomes is intentionally not checked —
165	 * it is not required by `add stressor`/`add purpose` in cli-schema.json.
166	 */
167	export function isForceValid(force: {
168	  description: string;
169	  attractorId: string;
170	  naiveChangeOrFeature: string;
171	  components: string[];
172	}): boolean {
173	  for (const field of REQUIRED_FORCE_FIELDS) {
174	    if (force[field] === "") return false;
175	  }
176	  return force.components.length > 0;
177	}
178	
179	/** Per-state validity: which forces (by id/tempId) are invalid, and why. */
180	export interface StateValidity {
181	  invalidForceIds: Set<string>;
182	  /** Reasons per invalid force id/tempId, e.g. ["description", "components"]. */
183	  invalidReasonsByForce: Record<string, string[]>;
184	}
185	
186	/**
187	 * Computes validity across the whole current state: every base force merged
188	 * with its pending update (if any), plus every added force. Used later to
189	 * drive red-highlighting of invalid cells/rows/sticky headers (Phase 5).
190	 */
191	export function computeStateValidity(state: PendingState): StateValidity {
192	  const invalidForceIds = new Set<string>();
193	  const invalidReasonsByForce: Record<string, string[]> = {};
194	
195	  const evaluate = (
196	    id: string,
197	    merged: {
198	      description: string;
199	      attractorId: string;
200	      naiveChangeOrFeature: string;
201	      components: string[];
202	    },
203	  ): void => {
204	    const reasons: string[] = [];
205	    for (const field of REQUIRED_FORCE_FIELDS) {
206	      if (merged[field] === "") reasons.push(field);
207	    }
208	    if (merged.components.length === 0) reasons.push("components");
209	    if (reasons.length > 0) {
210	      invalidForceIds.add(id);
211	      invalidReasonsByForce[id] = reasons;
212	    }
213	  };
214	
215	  for (const base of state.baseForces) {
216	    const update = state.updatedForces[base.id];
217	    evaluate(base.id, {
218	      description: update?.description ?? base.description,
219	      attractorId: update?.attractorId ?? base.attractorId,
220	      naiveChangeOrFeature: update?.naiveChangeOrFeature ?? base.naiveChangeOrFeature,
221	      components: update?.components ?? base.components,
222	    });
223	  }
224	
225	  for (const added of state.addedForces) {
226	    const update = state.updatedForces[added.tempId];
227	    evaluate(added.tempId, {
228	      description: update?.description ?? added.description,
229	      attractorId: update?.attractorId ?? added.attractorId,
230	      naiveChangeOrFeature: update?.naiveChangeOrFeature ?? added.naiveChangeOrFeature,
231	      components: update?.components ?? added.components,
232	    });
233	  }
234	
235	  return { invalidForceIds, invalidReasonsByForce };
236	}
237	
238	/**
239	 * Flattens a PendingState into the fixed emission order: components,
240	 * attractors, personas, terms, forces — with every addition across every
241	 * bucket ordered before every update across every bucket (see module notes
242	 * re: terms, and re: added forces with toggled components synthesizing a
243	 * follow-up "update" entry keyed by their tempId).
244	 */
245	export function orderedEntries(state: PendingState): OrderedEntry[] {
246	  const addedForceTempIds = new Set(state.addedForces.map((f) => f.tempId));
247	
248	  const adds: OrderedEntry[] = [
249	    ...state.addedComponents.map((c): OrderedEntry => ({ bucket: "component", action: "add", key: c.name })),
250	    ...state.addedAttractors.map((a): OrderedEntry => ({ bucket: "attractor", action: "add", key: a.name })),
251	    ...state.addedPersonas.map((p): OrderedEntry => ({ bucket: "persona", action: "add", key: p.name })),
252	    ...state.addedTerms.map((t): OrderedEntry => ({ bucket: "term", action: "add", key: t.term })),
253	    ...state.addedForces.map((f): OrderedEntry => ({ bucket: "force", action: "add", key: f.tempId })),
254	  ];
255	
256	  const updates: OrderedEntry[] = [
257	    ...Object.keys(state.updatedComponents).map(
258	      (k): OrderedEntry => ({ bucket: "component", action: "update", key: k }),
259	    ),
260	    ...Object.keys(state.updatedAttractors).map(
261	      (k): OrderedEntry => ({ bucket: "attractor", action: "update", key: k }),
262	    ),
263	    ...Object.keys(state.updatedPersonas).map(
264	      (k): OrderedEntry => ({ bucket: "persona", action: "update", key: k }),
265	    ),
266	    ...Object.keys(state.updatedTerms).map((k): OrderedEntry => ({ bucket: "term", action: "update", key: k })),
267	    // Synthetic follow-up updates for added forces whose toggled components
268	    // can't ride on their own `add` line (no --force-id known yet) — see
269	    // module notes and toCommandLines.
270	    ...state.addedForces
271	      .filter((f) => f.components.length > 0)
272	      .map((f): OrderedEntry => ({ bucket: "force", action: "update", key: f.tempId })),
273	    // Real diffs against base forces (or, in principle, further edits to an
274	    // added force after its synthetic entry was already emitted above —
275	    // excluded here to avoid a second, ambiguous entry for the same tempId).
276	    ...Object.keys(state.updatedForces)
277	      .filter((k) => !addedForceTempIds.has(k))
278	      .map((k): OrderedEntry => ({ bucket: "force", action: "update", key: k })),
279	  ];
280	
281	  return [...adds, ...updates];
282	}
283	
284	/** One rendered `residual add`/`residual update` command line, with its validity. */
285	export interface CommandLine {
286	  line: string;
287	  valid: boolean;
288	}
289	
290	/**
291	 * Renders a PendingState into ordered `residual add`/`residual update`
292	 * command-line text (see orderedEntries for ordering), quoting every flag
293	 * value in double quotes and escaping embedded `"` as `\"`, mirroring
294	 * import-parser.ts's `tokenizeCommandLine` so lines round-trip through its
295	 * `parseImportText`. Lines belonging to an invalid force (see isForceValid)
296	 * are marked `valid: false`; the DOM layer (Phase 5) decides whether to
297	 * comment such lines out with `# `.
298	 */
299	/** Double-quotes a value for CLI text, escaping embedded `"` as `\"` — mirrors import-parser.ts's `tokenizeCommandLine` unescaping. */
300	function quoteValue(value: string): string {
301	  return `"${value.replace(/"/g, '\\"')}"`;
302	}
303	
304	/** Renders `--flag "value"`. */
305	function flagText(name: string, value: string): string {
306	  return `--${name} ${quoteValue(value)}`;
307	}
308	
309	/** Sanitizes a tempId into a shell variable name: uppercase, non-alphanumeric runs -> "_", suffixed "_ID". */
310	function tempIdToVarName(tempId: string): string {
311	  return `${tempId.toUpperCase().replace(/[^A-Z0-9]+/g, "_")}_ID`;
312	}
313	
314	export function toCommandLines(state: PendingState): CommandLine[] {
315	  const validity = computeStateValidity(state);
316	  const entries = orderedEntries(state);
317	
318	  const addedComponentByName = new Map(state.addedComponents.map((c) => [c.name, c]));
319	  const addedAttractorByName = new Map(state.addedAttractors.map((a) => [a.name, a]));
320	  const addedPersonaByName = new Map(state.addedPersonas.map((p) => [p.name, p]));
321	  const addedTermByTerm = new Map(state.addedTerms.map((t) => [t.term, t]));
322	  const addedForceByTempId = new Map(state.addedForces.map((f) => [f.tempId, f]));
323	  const baseForceById = new Map(state.baseForces.map((f) => [f.id, f]));
324	
325	  const forceIsValid = (key: string): boolean => !validity.invalidForceIds.has(key);
326	
327	  const renderComponentAdd = (name: string): CommandLine => {
328	    const c = addedComponentByName.get(name)!;
329	    const line = [
330	      "residual add component",
331	      flagText("architecture-set", c.architectureSet),
332	      flagText("description", c.description),
333	      flagText("name", c.name),
334	      flagText("status", c.status),
335	    ].join(" ");
336	    return { line, valid: true };
337	  };
338	
339	  const renderComponentUpdate = (name: string): CommandLine => {
340	    const update = state.updatedComponents[name]!;
341	    const parts = ["residual update component", flagText("name", name)];
342	    if (update.architectureSet !== undefined) parts.push(flagText("architecture-set", update.architectureSet));
343	    if (update.description !== undefined) parts.push(flagText("description", update.description));
344	    if (update.status !== undefined) parts.push(flagText("status", update.status));
345	    return { line: parts.join(" "), valid: true };
346	  };
347	
348	  const renderAttractorAdd = (name: string): CommandLine => {
349	    const a = addedAttractorByName.get(name)!;
350	    const line = [
351	      "residual add attractor",
352	      flagText("description", a.description),
353	      flagText("name", a.name),
354	      flagText("negative-state", a.negativeState),
355	      flagText("positive-state", a.positiveState),
356	    ].join(" ");
357	    return { line, valid: true };
358	  };
359	
360	  const renderAttractorUpdate = (id: string): CommandLine => {
361	    const update = state.updatedAttractors[id]!;
362	    const parts = ["residual update attractor", flagText("id", id)];
363	    if (update.description !== undefined) parts.push(flagText("description", update.description));
364	    if (update.name !== undefined) parts.push(flagText("name", update.name));
365	    if (update.negativeState !== undefined) parts.push(flagText("negative-state", update.negativeState));
366	    if (update.positiveState !== undefined) parts.push(flagText("positive-state", update.positiveState));
367	    return { line: parts.join(" "), valid: true };
368	  };
369	
370	  const renderPersonaAdd = (name: string): CommandLine => {
371	    const p = addedPersonaByName.get(name)!;
372	    const parts = ["residual add persona"];
373	    if (p.concerns !== undefined) parts.push(flagText("concerns", p.concerns));
374	    if (p.desires !== undefined) parts.push(flagText("desires", p.desires));
375	    parts.push(flagText("name", p.name));
376	    parts.push(flagText("role", p.role));
377	    return { line: parts.join(" "), valid: true };
378	  };
379	
380	  const renderPersonaUpdate = (name: string): CommandLine => {
381	    const update = state.updatedPersonas[name]!;
382	    const parts = ["residual update persona"];
383	    if (update.concerns !== undefined) parts.push(flagText("concerns", update.concerns));
384	    if (update.desires !== undefined) parts.push(flagText("desires", update.desires));
385	    parts.push(flagText("name", name));
386	    if (update.role !== undefined) parts.push(flagText("role", update.role));
387	    return { line: parts.join(" "), valid: true };
388	  };
389	
390	  const renderTermAdd = (term: string): CommandLine => {
391	    const t = addedTermByTerm.get(term)!;
392	    const parts = ["residual add term", flagText("definition", t.definition)];
393	    if (t.domain !== undefined) parts.push(flagText("domain", t.domain));
394	    if (t.related !== undefined) parts.push(flagText("related", t.related));
395	    parts.push(flagText("term", t.term));
396	    return { line: parts.join(" "), valid: true };
397	  };
398	
399	  const renderTermUpdate = (term: string): CommandLine => {
400	    const update = state.updatedTerms[term]!;
401	    const parts = ["residual update term"];
402	    if (update.definition !== undefined) parts.push(flagText("definition", update.definition));
403	    if (update.domain !== undefined) parts.push(flagText("domain", update.domain));
404	    if (update.related !== undefined) parts.push(flagText("related", update.related));
405	    parts.push(flagText("term", term));
406	    return { line: parts.join(" "), valid: true };
407	  };
408	
409	  const renderForceAdd = (tempId: string): CommandLine => {
410	    const f = addedForceByTempId.get(tempId)!;
411	    // Full isForceValid (via forceIsValid/computeStateValidity), not just
412	    // the text-field check: "no components selected is invalid" applies to
413	    // the whole row, so a force with zero components must render its add
414	    // line as invalid too, even though components aren't literally a flag
415	    // on `add stressor`/`add purpose` (see module notes).
416	    const valid = forceIsValid(tempId);
417	    const flags = [
418	      flagText("attractor-id", f.attractorId),
419	      flagText("description", f.description),
420	      flagText("naive-change", f.naiveChangeOrFeature),
421	    ];
422	    if (f.outcomes !== "") flags.push(flagText("outcomes", f.outcomes));
423	    if (f.shortname !== "") flags.push(flagText("shortname", f.shortname));
424	
425	    if (f.components.length === 0) {
426	      return { line: ["residual add", f.kind, ...flags].join(" "), valid };
427	    }
428	
429	    // The id is server-assigned and only known from stdout on success
430	    // ("Added stressor S-NN") — capture it into a shell variable so the
431	    // synthetic follow-up `update` (below) never has to reference the
432	    // tempId as a literal --force-id, which would never exist in the CSVs.
433	    const varName = tempIdToVarName(tempId);
434	    const inner = ["residual add", f.kind, ...flags].join(" ");
435	    const line = `${varName}=$(${inner} | grep -oE '[A-Z]+-[0-9]+' | tail -1)`;
436	    return { line, valid };
437	  };
438	
439	  const renderForceUpdateSynthetic = (tempId: string): CommandLine => {
440	    const f = addedForceByTempId.get(tempId)!;
441	    const valid = forceIsValid(tempId);
442	    const varName = tempIdToVarName(tempId);
443	    const parts = [`residual update ${f.kind}`, `--force-id ${quoteValue(`$${varName}`)}`];
444	    for (const component of f.components) {
445	      parts.push(flagText("add-component", component));
446	    }
447	    return { line: parts.join(" "), valid };
448	  };
449	
450	  const renderForceUpdateReal = (id: string): CommandLine => {
451	    const base = baseForceById.get(id)!;
452	    const update = state.updatedForces[id]!;
453	    const valid = forceIsValid(id);
454	    const parts = [`residual update ${base.kind}`, `--force-id ${quoteValue(id)}`];
455	    if (update.description !== undefined) parts.push(flagText("description", update.description));
456	    if (update.attractorId !== undefined) parts.push(flagText("attractor-id", update.attractorId));
457	    if (update.naiveChangeOrFeature !== undefined) parts.push(flagText("naive-change", update.naiveChangeOrFeature));
458	    if (update.outcomes !== undefined) parts.push(flagText("outcomes", update.outcomes));
459	    if (update.shortname !== undefined) parts.push(flagText("shortname", update.shortname));
460	    if (update.components !== undefined) {
461	      const before = new Set(base.components);
462	      const after = new Set(update.components);
463	      const added = update.components.filter((c) => !before.has(c));
464	      const removed = base.components.filter((c) => !after.has(c));
465	      for (const c of added) parts.push(flagText("add-component", c));
466	      for (const c of removed) parts.push(flagText("remove-component", c));
467	    }
468	    return { line: parts.join(" "), valid };
469	  };
470	
471	  return entries.map((entry): CommandLine => {
472	    if (entry.bucket === "component") {
473	      return entry.action === "add" ? renderComponentAdd(entry.key) : renderComponentUpdate(entry.key);
474	    }
475	    if (entry.bucket === "attractor") {
476	      return entry.action === "add" ? renderAttractorAdd(entry.key) : renderAttractorUpdate(entry.key);
477	    }
478	    if (entry.bucket === "persona") {
479	      return entry.action === "add" ? renderPersonaAdd(entry.key) : renderPersonaUpdate(entry.key);
480	    }
481	    if (entry.bucket === "term") {
482	      return entry.action === "add" ? renderTermAdd(entry.key) : renderTermUpdate(entry.key);
483	    }
484	    // bucket === "force"
485	    if (entry.action === "add") return renderForceAdd(entry.key);
486	    return addedForceByTempId.has(entry.key)
487	      ? renderForceUpdateSynthetic(entry.key)
488	      : renderForceUpdateReal(entry.key);
489	  });
490	}
