1	// DOM-wiring layer for the live-editing NKP matrix (Phase 5 of
2	// residual/iterations/view-live-editing-plan.md). Attaches event listeners to
3	// an already-server-rendered `<table class="matrix">` (see
4	// src/view/components/matrix.rs for the exact markup contract this module
5	// binds to) and drives state transitions through the pure reducers in
6	// ./actions and the pure decision helpers in ./render-decisions /./model.
7	//
8	// This module owns DOM mutation only — it never invents business rules.
9	// Every state transition is delegated to toggleComponent / addForceRow /
10	// updateForceField (./actions); every "should this be marked invalid?"
11	// decision is delegated to computeInvalidMarks (./render-decisions).
12	//
13	// Design decisions (documented per repo instructions, pinned by
14	// matrix-interactions.test.ts):
15	//
16	// - `mount`'s third parameter is a plain `setState` callback (not a store);
17	//   an optional 4th-parameter `MountOptions.onChange` fires after every
18	//   state-mutating interaction, *after* `setState` has already been called,
19	//   so a later phase can hang command-textbox regeneration off it without
20	//   this module knowing anything about that textbox.
21	// - Double-click on a residue cell re-renders only that `<td>` in place
22	//   (updates `data-coupled` and text content) rather than the whole table —
23	//   cheaper, and the task spec explicitly allows either strategy.
24	// - Right-click on a `tr.force-row` (event delegated from the table, since
25	//   rows are added/removed dynamically) opens a minimal context menu
26	//   (`<ul role="menu">` with two `<li role="menuitem" data-action="...">`
27	//   entries: "Add row above" / "Add row below") appended to `document.body`
28	//   at the cursor position. Choosing an entry calls `addForceRow` with the
29	//   SAME kind (stressor/purpose) as the row that was right-clicked (reading
30	//   `data-force-kind`) — right-clicking a specific row is the only kind
31	//   signal available at that point, so inheriting it is the least surprising
32	//   default. The new row is inserted as a sibling `<tr class="force-row"
33	//   data-force-id="<tempId>">` immediately before/after the anchor row, and
34	//   rendered already in "edit mode": its `.force-detail` div starts visible
35	//   (not `hidden`) and shows `<input>`/`<select>` fields directly (no
36	//   read-only `<dl>`, no separate Edit button click needed) since a brand
37	//   new row has nothing meaningful to display in read-only form yet.
38	// - An existing row's non-NKP fields are only ever edited via an explicit
39	//   "Edit" `<button>` appended into `.force-detail` (after the `<dl>`) —
40	//   never via double-click (double-click is reserved for NKP cells).
41	//   Clicking "Edit" swaps `description` / `naive change` / `outcomes` `<dd>`s
42	//   for pre-filled `<input type="text">` elements and the `attractor` `<dd>`
43	//   for a `<select>` populated from `attractorOptions(state)` (current
44	//   attractor id pre-selected), and shows "OK"/"Cancel" buttons while hiding
45	//   "Edit".
46	// - "OK" calls `updateForceField` only for editable fields (description,
47	//   attractorId, naiveChangeOrFeature, outcomes) whose input/select value
48	//   differs from the value captured when "Edit" was clicked — NOT
49	//   unconditionally for all four. This deviates from an earlier draft of
50	//   this comment: `updateForceField` sets the field explicitly in
51	//   `updatedForces`/`addedForces` even when the new value equals the old
52	//   one, so an unconditional call is NOT a no-op for state-equality checks
53	//   (see matrix-interactions.test.ts's "clicking OK calls updateForceField
54	//   for the edited fields" test, which asserts `getState()` equals a state
55	//   produced by a single `updateForceField` call for only the one field the
56	//   test actually edited). After OK, the fields swap back to a read-only
57	//   `<dl>` showing the newly-saved values and "Edit" reappears.
58	// - "Cancel" discards the `<input>`/`<select>` values without calling
59	//   `updateForceField` at all, and swaps back to the read-only `<dl>` showing
60	//   the values that were current before "Edit" was clicked (which, since no
61	//   reducer ran, are simply the still-current `getState()` values).
62	// - Invalid-row marking: any force whose key is in
63	//   `computeInvalidMarks(state).invalidForceKeys` gets the CSS class
64	//   `"row-invalid"` applied to both its `th.sticky-col[data-force-id]`
65	//   sticky label cell AND its `tr.force-row` element, so a stylesheet can key
66	//   off either. `invalidComponentColumns` is walked generically (applying
67	//   `"row-invalid"`-equivalent marking to matching `th[data-component]`
68	//   header cells, were that set ever non-empty) even though it is always
69	//   empty today per render-decisions.ts's documented scoping — this module
70	//   does not special-case that emptiness, it just naturally does nothing
71	//   when the set is empty.
72	
73	import { addForceRow, toggleComponent, updateForceField } from "./actions";
74	import type { PendingState } from "./model";
75	import { attractorOptions, computeInvalidMarks } from "./render-decisions";
76	
77	/** Options controlling side effects mount() triggers beyond the DOM/state update itself. */
78	export interface MountOptions {
79	  /**
80	   * Called after every state-mutating interaction, once `setState` has
81	   * already been invoked with the new state. Lets a later phase (e.g. the
82	   * command-textbox regenerator) react to changes without this module
83	   * knowing about it.
84	   */
85	  onChange?: () => void;
86	}
87	
88	type EditableField = "description" | "attractorId" | "naiveChangeOrFeature" | "outcomes";
89	
90	interface EffectiveForceValues {
91	  description: string;
92	  attractorId: string;
93	  naiveChangeOrFeature: string;
94	  outcomes: string;
95	}
96	
97	/** Resolves the currently-effective (base/added merged with any pending update) text field values for a force key. */
98	function getEffectiveForceValues(state: PendingState, forceKey: string): EffectiveForceValues {
99	  const update = state.updatedForces[forceKey];
100	  const added = state.addedForces.find((f) => f.tempId === forceKey);
101	  const base = added ?? state.baseForces.find((f) => f.id === forceKey);
102	  return {
103	    description: update?.description ?? base?.description ?? "",
104	    attractorId: update?.attractorId ?? base?.attractorId ?? "",
105	    naiveChangeOrFeature: update?.naiveChangeOrFeature ?? base?.naiveChangeOrFeature ?? "",
106	    outcomes: update?.outcomes ?? base?.outcomes ?? "",
107	  };
108	}
109	
110	/** Resolves the currently-effective coupled-components list for a force key. */
111	function effectiveComponents(state: PendingState, forceKey: string): string[] {
112	  const added = state.addedForces.find((f) => f.tempId === forceKey);
113	  if (added !== undefined) return added.components;
114	  const base = state.baseForces.find((f) => f.id === forceKey);
115	  if (base === undefined) return [];
116	  return state.updatedForces[forceKey]?.components ?? base.components;
117	}
118	
119	/** Renders the "<id> · <name>" label used in the read-only attractor <dd>, matching src/view/components/matrix.rs's fixture shape. */
120	function getAttractorLabel(state: PendingState, attractorId: string): string {
121	  const attractor = [...state.baseAttractors, ...state.addedAttractors].find((a) => a.id === attractorId);
122	  return attractor ? `${attractor.id} · ${attractor.name}` : attractorId;
123	}
124	
125	function createTextInput(name: string, value: string): HTMLInputElement {
126	  const input = document.createElement("input");
127	  input.type = "text";
128	  input.name = name;
129	  input.value = value;
130	  return input;
131	}
132	
133	function createAttractorSelect(state: PendingState, selectedId: string): HTMLSelectElement {
134	  const select = document.createElement("select");
135	  for (const option of attractorOptions(state)) {
136	    const optionEl = document.createElement("option");
137	    optionEl.value = option.id;
138	    optionEl.textContent = option.name;
139	    select.appendChild(optionEl);
140	  }
141	  select.value = selectedId;
142	  return select;
143	}
144	
145	function createResidueCell(forceKey: string, componentName: string): HTMLTableCellElement {
146	  const td = document.createElement("td");
147	  td.setAttribute("data-residue-cell", "true");
148	  td.setAttribute("data-force-id", forceKey);
149	  td.setAttribute("data-component", componentName);
150	  td.setAttribute("data-coupled", "0");
151	  return td;
152	}
153	
154	/**
155	 * Attaches all live-editing interactions (cell toggle, row context menu,
156	 * field edit, invalid-row marking) to `table`, an already-present
157	 * `<table class="matrix">` server-rendered per src/view/components/matrix.rs.
158	 *
159	 * `getState`/`setState` give this module read/write access to the
160	 * caller-owned `PendingState` without owning it directly, mirroring the
161	 * reducer signatures in ./actions.
162	 */
163	/** Returned by `mount()` so callers driving state changes from outside this
164	 * module (e.g. the below-table stage-stressor/purpose forms in forms.ts) can
165	 * ask it to catch up: insert a `<tr>` for any `addedForces` entry that
166	 * doesn't have one yet, so every pending force stays reachable for NKP
167	 * toggling regardless of which UI surface created it. */
168	export interface MountResult {
169	  syncNewRows: () => void;
170	}
171	
172	export function mount(
173	  table: HTMLTableElement,
174	  getState: () => PendingState,
175	  setState: (next: PendingState) => void,
176	  options?: MountOptions,
177	): MountResult {
178	  function applyInvalidMarks(): void {
179	    const { invalidForceKeys } = computeInvalidMarks(getState());
180	    const rows = table.querySelectorAll<HTMLTableRowElement>("tr.force-row[data-force-id]");
181	    for (const row of Array.from(rows)) {
182	      const forceKey = row.getAttribute("data-force-id");
183	      if (forceKey === null) continue;
184	      const invalid = invalidForceKeys.has(forceKey);
185	      row.classList.toggle("row-invalid", invalid);
186	      row.querySelector("th.sticky-col[data-force-id]")?.classList.toggle("row-invalid", invalid);
187	    }
188	  }
189	
190	  function appendEditButton(detail: HTMLElement, forceKey: string): void {
191	    const button = document.createElement("button");
192	    button.type = "button";
193	    button.textContent = "Edit";
194	    button.addEventListener("click", () => enterEditMode(detail, forceKey));
195	    detail.appendChild(button);
196	  }
197	
198	  function renderReadOnly(detail: HTMLElement, forceKey: string): void {
199	    detail.innerHTML = "";
200	    const values = getEffectiveForceValues(getState(), forceKey);
201	    const dl = document.createElement("dl");
202	    const addPair = (term: string, value: string): void => {
203	      const dt = document.createElement("dt");
204	      dt.textContent = term;
205	      const dd = document.createElement("dd");
206	      dd.textContent = value;
207	      dl.append(dt, dd);
208	    };
209	    addPair("id", forceKey);
210	    addPair("attractor", getAttractorLabel(getState(), values.attractorId));
211	    addPair("description", values.description);
212	    addPair("naive change", values.naiveChangeOrFeature);
213	    addPair("outcomes", values.outcomes);
214	    detail.appendChild(dl);
215	    appendEditButton(detail, forceKey);
216	  }
217	
218	  function enterEditMode(detail: HTMLElement, forceKey: string): void {
219	    detail.innerHTML = "";
220	    const state = getState();
221	    const values = getEffectiveForceValues(state, forceKey);
222	
223	    const descriptionInput = createTextInput("description", values.description);
224	    const naiveChangeInput = createTextInput("naiveChangeOrFeature", values.naiveChangeOrFeature);
225	    const outcomesInput = createTextInput("outcomes", values.outcomes);
226	    const attractorSelect = createAttractorSelect(state, values.attractorId);
227	
228	    const okButton = document.createElement("button");
229	    okButton.type = "button";
230	    okButton.textContent = "OK";
231	    const cancelButton = document.createElement("button");
232	    cancelButton.type = "button";
233	    cancelButton.textContent = "Cancel";
234	
235	    okButton.addEventListener("click", () => {
236	      let next = getState();
237	      const edited: Array<[EditableField, string]> = [
238	        ["description", descriptionInput.value],
239	        ["attractorId", attractorSelect.value],
240	        ["naiveChangeOrFeature", naiveChangeInput.value],
241	        ["outcomes", outcomesInput.value],
242	      ];
243	      for (const [field, value] of edited) {
244	        if (value !== values[field]) {
245	          next = updateForceField(next, forceKey, field, value);
246	        }
247	      }
248	      setState(next);
249	      renderReadOnly(detail, forceKey);
250	      applyInvalidMarks();
251	      options?.onChange?.();
252	    });
253	
254	    cancelButton.addEventListener("click", () => {
255	      renderReadOnly(detail, forceKey);
256	    });
257	
258	    detail.append(descriptionInput, naiveChangeInput, outcomesInput, attractorSelect, okButton, cancelButton);
259	  }
260	
261	  function wireLiveField(
262	    el: HTMLInputElement | HTMLSelectElement,
263	    eventName: "input" | "change",
264	    forceKey: string,
265	    field: EditableField,
266	  ): void {
267	    el.addEventListener(eventName, () => {
268	      setState(updateForceField(getState(), forceKey, field, el.value));
269	      applyInvalidMarks();
270	      options?.onChange?.();
271	    });
272	  }
273	
274	  function buildNewForceRow(tempId: string, kind: "stressor" | "purpose"): HTMLTableRowElement {
275	    const state = getState();
276	    const components = [...state.baseComponents, ...state.addedComponents];
277	    const values = getEffectiveForceValues(state, tempId);
278	
279	    const tr = document.createElement("tr");
280	    tr.className = "force-row";
281	    tr.setAttribute("data-force-id", tempId);
282	    tr.setAttribute("data-force-kind", kind);
283	    tr.setAttribute("data-row-total", "0");
284	
285	    const th = document.createElement("th");
286	    th.className = "sticky-col";
287	    th.setAttribute("data-force-id", tempId);
288	
289	    const detail = document.createElement("div");
290	    detail.className = "force-detail";
291	
292	    const descriptionInput = createTextInput("description", values.description);
293	    const naiveChangeInput = createTextInput("naiveChangeOrFeature", values.naiveChangeOrFeature);
294	    const outcomesInput = createTextInput("outcomes", values.outcomes);
295	    const attractorSelect = createAttractorSelect(state, values.attractorId);
296	
297	    wireLiveField(descriptionInput, "input", tempId, "description");
298	    wireLiveField(naiveChangeInput, "input", tempId, "naiveChangeOrFeature");
299	    wireLiveField(outcomesInput, "input", tempId, "outcomes");
300	    wireLiveField(attractorSelect, "change", tempId, "attractorId");
301	
302	    detail.append(descriptionInput, naiveChangeInput, outcomesInput, attractorSelect);
303	    th.appendChild(detail);
304	    tr.appendChild(th);
305	
306	    for (const component of components) {
307	      tr.appendChild(createResidueCell(tempId, component.name));
308	    }
309	
310	    const totalTd = document.createElement("td");
311	    totalTd.className = "sticky-col-right";
312	    totalTd.setAttribute("data-row-total", "0");
313	    totalTd.textContent = "0";
314	    tr.appendChild(totalTd);
315	
316	    return tr;
317	  }
318	
319	  function closeContextMenu(): void {
320	    for (const el of Array.from(document.querySelectorAll('[role="menu"]'))) {
321	      el.remove();
322	    }
323	  }
324	
325	  function handleAddRow(anchorRow: HTMLTableRowElement, action: "add-above" | "add-below"): void {
326	    const kind: "stressor" | "purpose" = anchorRow.getAttribute("data-force-kind") === "purpose" ? "purpose" : "stressor";
327	    const { state: nextState, tempId } = addForceRow(getState(), kind);
328	    setState(nextState);
329	
330	    const newRow = buildNewForceRow(tempId, kind);
331	    const parent = anchorRow.parentElement;
332	    if (parent !== null) {
333	      parent.insertBefore(newRow, action === "add-above" ? anchorRow : anchorRow.nextSibling);
334	    }
335	
336	    applyInvalidMarks();
337	    options?.onChange?.();
338	  }
339	
340	  function openContextMenu(event: MouseEvent, anchorRow: HTMLTableRowElement): void {
341	    closeContextMenu();
342	    const menu = document.createElement("ul");
343	    menu.setAttribute("role", "menu");
344	    menu.style.position = "absolute";
345	    menu.style.left = `${event.clientX}px`;
346	    menu.style.top = `${event.clientY}px`;
347	
348	    const entries: Array<{ action: "add-above" | "add-below"; label: string }> = [
349	      { action: "add-above", label: "Add row above" },
350	      { action: "add-below", label: "Add row below" },
351	    ];
352	
353	    for (const { action, label } of entries) {
354	      const item = document.createElement("li");
355	      item.setAttribute("role", "menuitem");
356	      item.setAttribute("data-action", action);
357	      item.textContent = label;
358	      item.addEventListener("click", () => {
359	        handleAddRow(anchorRow, action);
360	        closeContextMenu();
361	      });
362	      menu.appendChild(item);
363	    }
364	
365	    document.body.appendChild(menu);
366	  }
367	
368	  table.addEventListener("dblclick", (event) => {
369	    const target = event.target;
370	    if (!(target instanceof Element)) return;
371	    const cell = target.closest('td[data-residue-cell]');
372	    if (!(cell instanceof HTMLTableCellElement)) return;
373	    const forceKey = cell.getAttribute("data-force-id");
374	    const component = cell.getAttribute("data-component");
375	    if (forceKey === null || component === null) return;
376	
377	    const next = toggleComponent(getState(), forceKey, component);
378	    setState(next);
379	
380	    const coupled = effectiveComponents(next, forceKey).includes(component);
381	    cell.setAttribute("data-coupled", coupled ? "1" : "0");
382	    cell.textContent = coupled ? "1" : "";
383	
384	    applyInvalidMarks();
385	    options?.onChange?.();
386	  });
387	
388	  table.addEventListener("contextmenu", (event) => {
389	    const target = event.target;
390	    if (!(target instanceof Element)) return;
391	    const row = target.closest("tr.force-row");
392	    if (!(row instanceof HTMLTableRowElement)) return;
393	    event.preventDefault();
394	    openContextMenu(event, row);
395	  });
396	
397	  for (const detail of Array.from(table.querySelectorAll<HTMLElement>(".force-detail"))) {
398	    if (detail.querySelector("dl") === null) continue;
399	    const forceKey = detail.closest("th[data-force-id]")?.getAttribute("data-force-id");
400	    if (forceKey === null || forceKey === undefined) continue;
401	    appendEditButton(detail, forceKey);
402	  }
403	
404	  function syncNewRows(): void {
405	    const tbody = table.querySelector("tbody");
406	    if (tbody === null) return;
407	    for (const force of getState().addedForces) {
408	      const selector = `tr.force-row[data-force-id="${CSS.escape(force.tempId)}"]`;
409	      if (table.querySelector(selector) !== null) continue;
410	      tbody.appendChild(buildNewForceRow(force.tempId, force.kind));
411	    }
412	    applyInvalidMarks();
413	  }
414	
415	  applyInvalidMarks();
416	
417	  return { syncNewRows };
418	}
