1	// DOM-wiring layer restoring the matrix-view interactions that used to live
2	// in an inline <script> in src/view/shell.html (live text filter, click-to-
3	// sort headers, accordion expand/collapse, fusion/fission threshold
4	// highlighting). That inline script was deleted wholesale while wiring in
5	// the new TS-based live-editing system (Phases 0-8 of
6	// residual/iterations/view-live-editing-plan.md) and never reimplemented —
7	// this module is the fix for that regression.
8	//
9	// Unlike matrix-interactions.ts / forms.ts, this module owns no application
10	// state: it is pure DOM presentation logic (filter/sort/accordion/fusion-
11	// fission-highlighting) layered on top of whatever `table.matrix` currently
12	// contains. Because matrix-interactions.ts and forms.ts can add rows/columns
13	// to that table at any time via their own `onChange` callbacks, every
14	// listener here is delegated on `container` (not bound per-row/per-header)
15	// so newly added elements are handled automatically without rewiring, and
16	// `recomputeFusionFission()` is exposed on the returned handle so a caller
17	// can force a recompute after a mutation it knows about (e.g. hang it off
18	// the same shared `onChange` callback matrix-interactions.ts/forms.ts already
19	// use).
20	//
21	// Threshold slider auto-initialization (min/max/value) happens once, at
22	// mount time, based on the number of `tr.force-row` present then — matching
23	// the original inline script's on-load behavior. It is intentionally not
24	// re-derived by `recomputeFusionFission()`.
25	
26	/** Options controlling mountMatrixView(); currently there are none, but the
27	 * shape is kept for parity with MountOptions/MountFormsOptions in the sibling
28	 * modules and to leave room for a future `onChange`-style hook. */
29	export interface MatrixViewOptions {
30	  onChange?: () => void;
31	}
32	
33	/** Returned by mountMatrixView() so a caller can force a fusion/fission
34	 * recompute after externally mutating the table (new rows/columns). */
35	export interface MatrixViewHandle {
36	  recomputeFusionFission: () => void;
37	}
38	
39	type SortDir = "asc" | "desc";
40	
41	function sortMatrixBy(container: HTMLElement, key: string, dir: SortDir): void {
42	  const table = container.querySelector("table.matrix");
43	  const tbody = table?.querySelector("tbody");
44	  if (!tbody) return;
45	  const rows = Array.from(tbody.querySelectorAll<HTMLTableRowElement>("tr.force-row"));
46	  const mult = dir === "desc" ? -1 : 1;
47	
48	  rows.sort((ra, rb) => {
49	    if (key === "force") {
50	      return (ra.getAttribute("data-force-id") ?? "").localeCompare(rb.getAttribute("data-force-id") ?? "") * mult;
51	    }
52	    if (key === "total") {
53	      return (Number(ra.getAttribute("data-row-total") ?? 0) - Number(rb.getAttribute("data-row-total") ?? 0)) * mult;
54	    }
55	    if (key.indexOf("component:") === 0) {
56	      const comp = key.slice("component:".length);
57	      const ca = ra.querySelector(`td[data-component="${CSS.escape(comp)}"]`);
58	      const cb = rb.querySelector(`td[data-component="${CSS.escape(comp)}"]`);
59	      const va = ca?.getAttribute("data-coupled") === "1" ? 1 : 0;
60	      const vb = cb?.getAttribute("data-coupled") === "1" ? 1 : 0;
61	      return (va - vb) * mult;
62	    }
63	    return 0;
64	  });
65	
66	  for (const row of rows) tbody.appendChild(row);
67	}
