74	function computeMatrixCandidates(container: HTMLElement): FusionFissionResult {
75	  const table = container.querySelector("table.matrix");
76	  const fusion = new Set<string>();
77	  const fission = new Set<string>();
78	  if (!table) return { fusion, fission };
79	
80	  const componentNames = Array.from(table.querySelectorAll("thead th[data-component]")).map(
81	    (th) => th.getAttribute("data-component") ?? "",
82	  );
83	
84	  const vectors: Record<string, Record<string, boolean>> = {};
85	  for (const name of componentNames) vectors[name] = {};
86	
87	  for (const td of Array.from(table.querySelectorAll("tbody td[data-residue-cell]"))) {
88	    const comp = td.getAttribute("data-component") ?? "";
89	    const force = td.getAttribute("data-force-id") ?? "";
90	    if (vectors[comp]) vectors[comp][force] = td.getAttribute("data-coupled") === "1";
91	  }
92	
93	  for (let i = 0; i < componentNames.length; i++) {
94	    for (let j = i + 1; j < componentNames.length; j++) {
95	      const a = vectors[componentNames[i]];
96	      const b = vectors[componentNames[j]];
97	      const forceIds = Object.keys(a);
98	      const identical = forceIds.length > 0 && forceIds.every((fid) => a[fid] === b[fid]);
99	      if (identical) {
100	        fusion.add(componentNames[i]);
101	        fusion.add(componentNames[j]);
102	      }
103	    }
104	  }
105	
106	  const thresholdInput = container.querySelector("[data-threshold-input]");
107	  const threshold = thresholdInput instanceof HTMLInputElement ? Number(thresholdInput.value) : 1;
108	
109	  for (const td of Array.from(table.querySelectorAll("tfoot td[data-col-total]"))) {
110	    const total = Number(td.getAttribute("data-col-total"));
111	    if (total > threshold) fission.add(td.getAttribute("data-component") ?? "");
112	  }
113	
114	  return { fusion, fission };
115	}
