77	/** Options controlling side effects mount() triggers beyond the DOM/state update itself. */
78	export interface MountOptions {
79	  /**
80	   * Called after every state-mutating interaction, once `setState` has
81	   * already been invoked with the new state. Lets a later phase (e.g. the
82	   * command-textbox regenerator) react to changes without this module
83	   * knowing about it.
84	   */
85	  onChange?: () => void;
86	}
