function createTextInput(name: string, value: string): HTMLInputElement {
  const input = document.createElement("input");
  input.type = "text";
  input.name = name;
  input.value = value;
  return input;
}

/**
 * Wraps a field element in a `<label>` carrying its visible text, matching
 * the labeled-field pattern already used by the below-table "Stage adds"
 * forms (src/view/shell.html). Without a label wrapper, matrix-interactions'
 * inline row editor (`enterEditMode`/`buildNewForceRow`) rendered bare
 * `<input>`/`<select>` elements with no visible field name, AND — since
 * `label { display: block }` is the only block-level ancestor in that
 * layout path — no wrapper meant fields could pack onto one line and
 * overflow the sticky force column sideways instead of stacking.
 */
function labeledField(labelText: string, field: HTMLElement): HTMLLabelElement {
  const label = document.createElement("label");
  label.textContent = labelText;
  label.appendChild(field);
  return label;
}

function createKindSelect(selected: "stressor" | "purpose"): HTMLSelectElement {
  const select = document.createElement("select");
  for (const kind of ["stressor", "purpose"] as const) {
    const option = document.createElement("option");
    option.value = kind;
    option.textContent = kind;
    select.appendChild(option);
  }
  select.value = selected;
  return select;
}

